     1	import type { Item } from "./insured-item.js";
     2	import { insuranceValue } from "./price-list.js";
     3	
     4	export interface Damage {
     5	  itemType: string;
     6	  amount: number;
     7	}
     8	
     9	export interface Incident {
    10	  cause: string;
    11	  damages: Damage[];
    12	}
    13	
    14	export interface Policy {
    15	  insuredItems: Item[];
    16	  // How much the MHPCO may still pay out over this policy's lifetime.
    17	  remainingCap: number;
    18	}
    19	
    20	export interface ClaimResult {
    21	  payout: number;
    22	  remainingCap: number;
    23	  // The policy as it stands after this claim, for settling the next one.
    24	  policy: Policy;
    25	}
    26	
    27	const DEDUCTIBLE_PER_DAMAGE = 100;
    28	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    29	
    30	// The MHPCO insures a policy for the sum of its items' insurance values.
    31	function insuranceSum(insuredItems: Item[]): number {
    32	  return insuredItems
    33	    .map(insuranceValue)
    34	    .reduce((sum, value) => sum + value, 0);
    35	}
    36	
    37	// The MHPCO pays out at most twice the insurance sum over a policy's lifetime.
    38	// A policy is opened with that whole cap intact; each claim depletes it.
    39	export function openPolicy(insuredItems: Item[]): Policy {
    40	  return {
    41	    insuredItems,
    42	    remainingCap: insuranceSum(insuredItems) * CAP_MULTIPLE_OF_INSURANCE_SUM,
    43	  };
    44	}
    45	
    46	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
    47	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
    48	const FULL_REIMBURSEMENT_RATE = 1;
    49	
    50	function damagedItem(policy: Policy, damage: Damage): Item | undefined {
    51	  return policy.insuredItems.find((item) => item.type === damage.itemType);
    52	}
    53	
    54	function isHighlyEnchanted(item: Item): boolean {
    55	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
    56	}
    57	
    58	// Which reimbursement clause covers the damaged item. Damage to a highly
    59	// enchanted item is reimbursed at half; all other damage in full.
    60	// The dragon-material clause is subsumed by that default: it reimburses in
    61	// full, and where it meets the high-enchantment clause the 50 % rate wins, so
    62	// it never changes a payout and needs no branch of its own.
    63	// An item the policy does not list has no clause and is reimbursed in full --
    64	// rejecting such a damage entry is a separate, not yet implemented rule.
    65	function reimbursementRateFor(item: Item | undefined): number {
    66	  if (item !== undefined && isHighlyEnchanted(item)) {
    67	    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
    68	  }
    69	  return FULL_REIMBURSEMENT_RATE;
    70	}
    71	
    72	// The MHPCO settles each damage event separately: it reimburses the damage
    73	// under the applicable clause, then withholds its deductible once per event.
    74	function settlementForDamageEvent(policy: Policy, damage: Damage): number {
    75	  const rate = reimbursementRateFor(damagedItem(policy, damage));
    76	  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
    77	}
    78	
    79	export function claim(policy: Policy, incident: Incident): ClaimResult {
    80	  const cap = policy.remainingCap;
    81	  const settled = incident.damages
    82	    .map((damage) => settlementForDamageEvent(policy, damage))
    83	    .reduce((sum, amount) => sum + amount, 0);
    84	  const payout = Math.min(settled, cap);
    85	  const remainingCap = cap - payout;
    86	  return { payout, remainingCap, policy: { ...policy, remainingCap } };
    87	}
