const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
const FULL_REIMBURSEMENT_RATE = 1;

// A damage entry names only the type of the item it befell, so the MHPCO can
// identify the damaged item no further than the policy's first insured item of
// that type. Where a policy covers several alike items this is a deliberate
// approximation: alike items share the traits the reimbursement clauses read,
// so any of them yields the same clause. Counting damage entries against the
// insured items of their type -- and rejecting an excess -- is a separate rule
// the MHPCO has not yet put into force.
function firstInsuredItemOfType(
  policy: Policy,
  damage: Damage,
): Item | undefined {
  return policy.insuredItems.find((item) => item.type === damage.itemType);
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
}

// Which reimbursement clause covers the damaged item. Damage to a highly
// enchanted item is reimbursed at half; all other damage in full.
// The dragon-material clause is subsumed by that default: it reimburses in
// full, and where it meets the high-enchantment clause the 50 % rate wins, so
// it never changes a payout and needs no branch of its own.
// An item the policy does not list has no clause and is reimbursed in full --
// rejecting such a damage entry is a separate, not yet implemented rule.
function reimbursementRateFor(item: Item | undefined): number {
  if (item !== undefined && isHighlyEnchanted(item)) {
    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
  }
  return FULL_REIMBURSEMENT_RATE;
}

